// Two inputs: FB post text (ExtractWithClaude) or a screenshot of the post (ReadScreenshot, Claude vision).
const fromImage = $('ReadScreenshot').isExecuted;
const src = fromImage ? $('IsScreenshot').item.json : $('PostInput').item.json;
// The output shape differs per Anthropic node operation → look for the text in all known fields.
const blocks = Array.isArray($json.content) ? $json.content : [];
const fromBlocks = blocks.filter(c => c.type === 'text').map(c => c.text).join('');
const raw = String($json.merged_response || fromBlocks || $json.text || $json.output || $json.message?.content || '');
const a = raw.indexOf('{');
const b = raw.lastIndexOf('}');
let p = null;
try { p = JSON.parse(raw.slice(a, b + 1)); } catch (e) { p = null; }
if (!p) {
  return { json: { id: '', parse_error: true, raw_odgovor: raw.slice(0, 300) } };
}
const cena = (p.cena === null || p.cena === undefined) ? null : Number(p.cena);
const m2 = (p.m2 === null || p.m2 === undefined) ? null : Number(p.m2);
const sobe = (p.sobe === null || p.sobe === undefined) ? null : Number(p.sobe);
const namesten = p.namesten || 'nepoznato';
// id: for text, a hash of the text; for a screenshot, a hash of the extracted fields (same listing sent twice → same id → dedup).
const key = fromImage ? ['img', cena, m2, sobe, p.opstina, p.naselje, p.naslov].join('|').toLowerCase() : String(src.text);
let h = 5381;
for (let i = 0; i < key.length; i++) { h = ((h * 33) ^ key.charCodeAt(i)) >>> 0; }
// Photo quality from the screenshot (same 1–5 scale as `Enrich - photo quality`): kvalitet = mean of condition and furnishing.
const score15 = v => { const n = Number(v); return v === null || v === undefined || v === '' || !Number.isFinite(n) ? null : Math.min(5, Math.max(1, n)); };
const photoParts = fromImage ? [score15(p.stanje_slike), score15(p.opremljenost_slike)].filter(x => x !== null) : [];
const kvalitet = photoParts.length ? Math.round(photoParts.reduce((x, y) => x + y, 0) / photoParts.length * 10) / 10 : null;
const CYR = { 'а':'a','б':'b','в':'v','г':'g','д':'d','ђ':'đ','е':'e','ж':'ž','з':'z','и':'i','ј':'j','к':'k','л':'l','љ':'lj','м':'m','н':'n','њ':'nj','о':'o','п':'p','р':'r','с':'s','т':'t','ћ':'ć','у':'u','ф':'f','х':'h','ц':'c','ч':'č','џ':'dž','ш':'š' };
const lat = t => t.replace(/[Ѐ-ӿ]/g, ch => { const low = ch.toLowerCase(); const r = CYR[low] ?? ''; return ch === low ? r : r.charAt(0).toUpperCase() + r.slice(1); });
const kvalitetOpis = kvalitet !== null && typeof p.slike_opis === 'string' && p.slike_opis.trim() ? lat(p.slike_opis.trim()).slice(0, 80) : null;
const grupa = src.grupa && src.grupa !== 'fb' ? 'fb:' + src.grupa : 'fb';
const prosao = p.jeste_ponuda === true && (cena === null || cena <= 600) && (m2 === null || m2 >= 30) && (sobe === null || sobe >= 1.5) && namesten !== 'ne';
return { json: {
  id: (fromImage ? 'fb_img_' : 'fb_') + h.toString(16),
  izvor: grupa + (fromImage ? ':screenshot' : ''),
  url: src.url || '',
  naslov: p.naslov || 'FB oglas',
  cena: cena,
  m2: m2,
  sobe: sobe,
  opstina: p.opstina || '',
  naselje: p.naselje || '',
  namesten: namesten,
  placanje: 'month',
  objavljeno: null,
  slika: '',
  upisano: new Date().toISOString(),
  prosao_filter: prosao,
  jeste_ponuda: p.jeste_ponuda === true,
  depozit_eur: p.depozit_eur ?? null,
  kucni_ljubimci: p.kucni_ljubimci || 'nepoznato',
  provizija: p.provizija ?? null,
  rezije_eur: p.rezije_eur ?? null,
  min_period_meseci: p.min_period_meseci ?? null,
  sumnjiv_oglas: p.sumnjiv_oglas === true,
  sumnjiv_razlog: p.sumnjiv_razlog ?? null,
  kvalitet,
  kvalitet_opis: kvalitetOpis
} };

// Is this flat already in the database from a listing site? Candidate = same price + m² + rooms + municipality in the last 30 days (FindSameFlat).
// A screenshot is sent along so Claude can compare the photos in the post with the candidate's cover photo.
const L = $('NormalizeFbListing').item.json;
const r = $json;
const fields = (r.schema?.fields || []).map(f => f.name);
const rows = (r.rows || []).map(row => Object.fromEntries(row.f.map((c, i) => [fields[i], c.v])));
const cand = rows[0];
if (!L.id || !cand) return { json: { listing: L, has_candidate: false } };
const num = v => v === null || v === undefined ? null : Number(v);
const postojeci = { ...cand, cena: num(cand.cena), m2: num(cand.m2), sobe: num(cand.sobe), ocena: num(cand.ocena), lok: num(cand.lok), kvalitet: num(cand.kvalitet) };
const fromImage = $('ReadScreenshot').isExecuted;
const bin = fromImage ? $('IsScreenshot').item.binary?.data : null;
return { json: { novi: L, postojeci, has_candidate: true }, ...(bin ? { binary: { data: bin } } : {}) };

// Result of the same-flat check merged into the listing as flat dup_* fields (BigQuery load ignores unknown fields).
// dup_isti: true = Claude confirmed the same flat, false = different flat, null = could not compare (e.g. text post without photos).
const pick = $('PickCandidate').item.json;
const L = pick.novi ?? pick.listing ?? {};
if (!pick.has_candidate) return { json: L };
const c = pick.postojeci;
const isti = typeof $json.isti === 'boolean' ? $json.isti : null;
return { json: { ...L, dup_isti: isti, dup_razlog: $json.razlog ?? null, dup_id: c.id, dup_url: c.url, dup_izvor: c.izvor, dup_ocena: c.ocena, dup_lok: c.lok, dup_kvalitet: c.kvalitet, dup_kvalitet_opis: c.kvalitet_opis ?? null } };
